/**
 * DEV-ONLY GLSL guest presets. This entire module is imported by glslPresets.ts
 * ONLY inside a `process.env.NODE_ENV === 'development'` guard, so Next.js
 * dead-code-eliminates it — and the embedded cubemap data URIs below — from the
 * production bundle. It must never be imported unconditionally.
 *
 * The E2E "Kitchen Sink" preset exercises the entire multipass + channel surface
 * (all 4 buffers + every GuestChannelKind + self-feedback + uValue slots) so a
 * browser render proves the pipeline end to end. It ships an embedded cubemap
 * (6 faces, 128px, derived from a CC0 Kenney space skybox) so Buffer C renders
 * without a manual upload. Image2d (Buffer B) and video (Buffer D) are still
 * user-supplied.
 *
 * GENERATED by scratch tooling — do not hand-edit the data URIs.
 */
import type { GlslPreset } from './glslPresets';
import type { AudioRoutingTable, AudioSourceId } from '@/types/effects/audio-routing';
import { DEFAULT_AUDIO_REACTIVE } from '@/types/effects/audio-reactive';

/**
 * Dev routing table for the uValue sweep: wires slots 1..8 to distinct audio
 * sources with a snappy envelope so each bar reacts to a different band. Slots
 * 5-8 reuse sources (only 4 bands + beat exist) so every bar moves with audio.
 */
const SWEEP_SOURCES: AudioSourceId[] = [
  'bass',
  'mid',
  'high',
  'energy',
  'beat',
  'bass',
  'mid',
  'high',
];
const SWEEP_ROUTING: AudioRoutingTable = {
  slots: SWEEP_SOURCES.map((source) => ({
    source,
    shape: {
      ...DEFAULT_AUDIO_REACTIVE,
      enabled: true,
      // band is unused for routing (source drives it) but the type requires it.
      band:
        source === 'beat' || source.startsWith('band:')
          ? 'energy'
          : (source as (typeof DEFAULT_AUDIO_REACTIVE)['band']),
      min: 0,
      max: 1,
      attack: 0.02,
      decay: 0.08,
    },
  })),
  customBands: [],
};

const CUBE_POSX =
  'data:image/png;base64,';
const CUBE_NEGX =
  'data:image/png;base64,';
const CUBE_POSY =
  'data:image/png;base64,';
const CUBE_NEGY =
  'data:image/png;base64,';
const CUBE_POSZ =
  'data:image/png;base64,';
const CUBE_NEGZ =
  'data:image/png;base64,';

/** Embedded space cubemap faces (GL order +X,-X,+Y,-Y,+Z,-Z), dev-only. */
const E2E_CUBEMAP_FACES: string[] = [
  CUBE_POSX,
  CUBE_NEGX,
  CUBE_POSY,
  CUBE_NEGY,
  CUBE_POSZ,
  CUBE_NEGZ,
];

/** Embedded default image (city-vibes bg, 256px) for Buffer B, dev-only. */
const E2E_IMAGE2D =
  'data:image/png;base64,';

export const E2E_KITCHEN_SINK: GlslPreset = {
  id: 'e2e-kitchen-sink',
  label: 'E2E Kitchen Sink (dev — all buffers + channels)',
  description:
    'DEV-ONLY coverage test: all 4 buffers + every channel kind (audio/image2d/cubemap/buffer/video) + self-feedback + uValue slots. Ships an embedded cubemap (Buffer C); upload an image (Buffer B iCh0) and a video (Buffer D iCh0) to light the rest.',
  source: `// Image: composite A/B/C/D into quadrants, tinted by uValue2.
//
// EXPECTED RESULT (all four quadrants should be lit with zero uploads):
//   • bottom-left  (Buffer A): bright cyan pulsing ring with a fading feedback
//     trail — the most "alive" quadrant, reacts to audio.
//   • bottom-right (Buffer B): the embedded city-vibes image, gently warped by A.
//   • top-left     (Buffer C): the embedded starfield cubemap, sweeping as uValue1
//     animates the view direction.
//   • top-right    (Buffer D): the track's BACKGROUND video, mixed 50/50
//     with Buffer B. If no background video is set on the project, this quadrant
//     is dark until one is.
//   Overall brightness scales with uValue2 (route audio into it to see it breathe).
//   A BLACK quadrant means that channel's asset failed to bind — check its tab.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec3 col;
  if (uv.x < 0.5 && uv.y < 0.5)       col = texture(iChannel0, uv * 2.0).rgb;                     // A
  else if (uv.x >= 0.5 && uv.y < 0.5) col = texture(iChannel1, (uv - vec2(0.5, 0.0)) * 2.0).rgb; // B
  else if (uv.x < 0.5 && uv.y >= 0.5) col = texture(iChannel2, (uv - vec2(0.0, 0.5)) * 2.0).rgb; // C
  else                                col = texture(iChannel3, (uv - vec2(0.5, 0.5)) * 2.0).rgb; // D
  col *= 0.6 + 0.8 * uValue2;                                // routed uValue2 slot
  fragColor = vec4(col, 1.0);
}`,
  channelKinds: ['buffer', 'buffer', 'buffer', 'buffer'],
  bufferRefs: ['a', 'b', 'c', 'd'],
  buffers: {
    a: {
      source: `// Buffer A: audio-reactive feedback trail (self-feedback via iChannel0=Buffer A).
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  float bass = texture(iChannel1, vec2(0.05, 0.25)).x;      // iChannel1 = audio FFT
  vec2 c = uv - 0.5;
  float r = length(c);
  float ring = smoothstep(0.02, 0.0, abs(r - (0.15 + 0.25 * bass)));
  vec3 prev = texture(iChannel0, uv + 0.003 * normalize(c + 1e-5)).rgb; // self, drifting inward
  vec3 col = prev * 0.94 + ring * vec3(0.2, 0.6, 1.0);
  fragColor = vec4(col, 1.0);
}`,
      channelKinds: ['buffer', 'audio', 'none', 'none'],
      bufferRefs: ['a', undefined, undefined, undefined],
    },
    b: {
      source: `// Buffer B: warp an uploaded image (iChannel0=image2d) by Buffer A's brightness.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec3 a = texture(iChannel1, uv).rgb;                       // iChannel1 = Buffer A
  float warp = dot(a, vec3(0.333)) * 0.04;
  vec3 img = texture(iChannel0, uv + warp).rgb;              // iChannel0 = image2d (user upload)
  img *= iChannelIntensity[0];
  fragColor = vec4(mix(img, a, 0.25), 1.0);
}`,
      channelKinds: ['image2d', 'buffer', 'none', 'none'],
      bufferRefs: [undefined, 'a', undefined, undefined],
      // Embedded default image seeded into iChannel0 on apply (dev-only asset).
      embeddedImage: { channel: 0, dataUri: E2E_IMAGE2D },
    },
    c: {
      source: `// Buffer C: sample the embedded cubemap (iChannel0=cubemap) along a uValue1-animated dir.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec2 p = uv * 2.0 - 1.0;
  float a = iTime * 0.3 + uValue1 * 6.2831;                  // routed uValue1 slot
  vec3 dir = normalize(vec3(p.x, p.y, cos(a)));
  vec3 env = texture(iChannel0, dir).rgb;                    // iChannel0 = samplerCube
  fragColor = vec4(env, 1.0);
}`,
      channelKinds: ['cubemap', 'none', 'none', 'none'],
      // Embedded cubemap seeded into iChannel0 on apply (dev-only asset).
      embeddedCubemap: { channel: 0, faces: E2E_CUBEMAP_FACES },
    },
    d: {
      source: `// Buffer D: mix a video frame (iChannel0=video) with Buffer B.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec3 vid = texture(iChannel0, uv).rgb;                     // iChannel0 = video
  vec3 b = texture(iChannel1, uv).rgb;                       // iChannel1 = Buffer B
  fragColor = vec4(mix(vid, b, 0.5), 1.0);
}`,
      // iCh0 video sourced from the track BACKGROUND video,
      // not an upload — the loader treats an unset videoSource as 'background'.
      channelKinds: ['video', 'buffer', 'none', 'none'],
      bufferRefs: [undefined, 'b', undefined, undefined],
    },
  },
};

/* ────────────────────────────────────────────────────────────────────────────
 * Individual edge-case debug shaders (dev-only).
 *
 * Each isolates ONE concern so a failure points at exactly one subsystem, unlike
 * the Kitchen Sink which lights everything at once. All dev-only (stripped from
 * prod with this module). Use them to expose regressions the coverage test hides.
 * ──────────────────────────────────────────────────────────────────────────── */

/** 1. Single-buffer self-feedback — proves ping-pong swap, decay, and NO
 * uninitialized-garbage on frame 0 (the black-clear-on-create guarantee). A
 * bright dot is injected each frame and the buffer decays its own last frame;
 * a correct pipeline shows a fading trail, a broken one shows garbage or a
 * hard-edged non-decaying smear. */
const DEBUG_SELF_FEEDBACK: GlslPreset = {
  id: 'debug-self-feedback',
  label: 'Debug · Single-buffer self-feedback',
  description:
    'DEV: Buffer A samples ITSELF (ping-pong). Injects a moving dot + decays last frame. Correct = smooth fading trail; broken = garbage on frame 0 or no decay.',
  source: `// EXPECTED: a bright orange dot orbits the center leaving a smooth fading
// comet trail. Frame 0 is clean black (no garbage). If the trail does NOT
// fade, or the screen shows noise/garbage, the ping-pong swap or the
// clear-on-create is broken.
void mainImage(out vec4 o, in vec2 fc){ o = texture(iChannel0, fc/iResolution.xy); }`,
  channelKinds: ['buffer', 'none', 'none', 'none'],
  bufferRefs: ['a', undefined, undefined, undefined],
  buffers: {
    a: {
      source: `void mainImage(out vec4 o, in vec2 fc){
  vec2 uv = fc/iResolution.xy;
  vec3 prev = texture(iChannel0, uv).rgb * 0.96;          // decayed self last-frame
  vec2 dot = vec2(0.5 + 0.35*cos(iTime), 0.5 + 0.35*sin(iTime*1.3));
  float d = smoothstep(0.03, 0.0, distance(uv, dot));
  o = vec4(prev + d*vec3(1.0, 0.5, 0.2), 1.0);
}`,
      channelKinds: ['buffer', 'none', 'none', 'none'],
      bufferRefs: ['a', undefined, undefined, undefined],
    },
  },
};

/** 2. Cubemap face-orientation probe — reuses the embedded cubemap and sweeps
 * the sampled direction across all 6 axes with time, overlaying which axis is
 * being sampled. Exposes face-order / vflip / handedness bugs (a face showing
 * on the wrong axis, or mirrored). */
const DEBUG_CUBEMAP_ORIENTATION: GlslPreset = {
  id: 'debug-cubemap-orientation',
  label: 'Debug · Cubemap face-orientation probe',
  description:
    'DEV: sweeps the sampled cubemap direction through ±X/±Y/±Z over time (embedded cubemap). Exposes face-order / vflip / handedness bugs — a face on the wrong axis or mirrored.',
  source: `// EXPECTED: the starfield fills the screen and the whole view swings through
// the 6 cube faces, ~1s each. A thin stripe at the bottom shows the current
// axis as a color (bright = +X/+Y/+Z, dim = negative). A face on the WRONG
// axis or looking mirrored/upside-down means a face-order or vflip bug.
void mainImage(out vec4 o, in vec2 fc){
  vec2 uv = fc/iResolution.xy;
  // Pick an axis by time; tile screen into the face view.
  float t = mod(iTime*0.5, 6.0);
  vec3 dir;
  if      (t<1.0) dir = vec3( 1, 0, 0);
  else if (t<2.0) dir = vec3(-1, 0, 0);
  else if (t<3.0) dir = vec3( 0, 1, 0);
  else if (t<4.0) dir = vec3( 0,-1, 0);
  else if (t<5.0) dir = vec3( 0, 0, 1);
  else            dir = vec3( 0, 0,-1);
  // Add screen-space tilt so the face fills the view.
  dir = normalize(dir + vec3((uv.x-0.5)*0.8, (uv.y-0.5)*0.8, 0.0));
  vec3 c = texture(iChannel0, dir).rgb;
  // Axis-tint stripe at the bottom so you can read which axis is live.
  if (uv.y < 0.06) c = 0.5 + 0.5*dir;
  o = vec4(c, 1.0);
}`,
  channelKinds: ['cubemap', 'none', 'none', 'none'],
  bufferRefs: [undefined, undefined, undefined, undefined],
  embeddedCubemap: { channel: 0, faces: E2E_CUBEMAP_FACES },
};

/** 3. All-channels-None — every channel unbound. The whole frame MUST be black
 * (unbound reads vec4(0)); any color means a channel is leaking a texture (the
 * exact audio-leak regression fixed earlier). */
const DEBUG_ALL_NONE: GlslPreset = {
  id: 'debug-all-none',
  label: 'Debug · All-channels-None (black fallback)',
  description:
    'DEV: all 4 channels None. Sums texture(iChannelN) — MUST be pure black. Any color = a channel is leaking a bound texture (the black-texture-fallback regression).',
  source: `// EXPECTED: PURE BLACK everywhere except a faint gray frame border (proof the
// pass ran). Any colour at all means an unbound channel is leaking a texture —
// the black-texture-fallback regression is back.
void mainImage(out vec4 o, in vec2 fc){
  vec2 uv = fc/iResolution.xy;
  vec4 s = texture(iChannel0, uv) + texture(iChannel1, uv)
         + texture(iChannel2, uv) + texture(iChannel3, uv);
  // Faint frame border so you can see the pass is running at all.
  float b = step(0.99, max(abs(uv.x-0.5), abs(uv.y-0.5))*2.0);
  o = vec4(s.rgb + b*vec3(0.15), 1.0);
}`,
  channelKinds: ['none', 'none', 'none', 'none'],
};

/** 4. uValue routing sweep — draws 8 horizontal bars, one per uValue1..8, each
 * bar length = its slot value. Exposes uniform-packing / routing drift (a slot
 * reading a neighbor's value, or stuck at 0). Route audio into the slots to see
 * them move. */
const DEBUG_UVALUE_SWEEP: GlslPreset = {
  id: 'debug-uvalue-sweep',
  label: 'Debug · uValue routing sweep (1..8)',
  description:
    'DEV: 8 bars, one per uValue1..8, length = slot value. Route audio into slots via the router; exposes uniform-packing / routing drift (wrong slot, stuck at 0).',
  source: `// EXPECTED: 8 horizontal bars stacked top-to-bottom, one per uValue1..8, each
// a different tint. A bar's LENGTH = that slot's value (0..1). With nothing
// routed all bars are empty (length 0). Route audio into a slot and only that
// bar should move — a neighbor moving instead means uniform-packing/routing drift.
void mainImage(out vec4 o, in vec2 fc){
  vec2 uv = fc/iResolution.xy;
  int row = int(uv.y * 8.0);
  row = clamp(row, 0, 7);
  // Select the slot value WITHOUT dynamic array indexing — a local float[8]
  // indexed by a computed int is a known GLSL ES 3.00 driver hazard (some
  // drivers read 0 for one index), which blanked a single bar. An explicit
  // if-chain reads every uValue as a plain uniform and is portable.
  float v = 0.0;
  if (row == 0) v = uValue1;
  else if (row == 1) v = uValue2;
  else if (row == 2) v = uValue3;
  else if (row == 3) v = uValue4;
  else if (row == 4) v = uValue5;
  else if (row == 5) v = uValue6;
  else if (row == 6) v = uValue7;
  else v = uValue8;
  v = clamp(v, 0.0, 1.0);
  float bar = step(uv.x, v);
  // Row tint so each slot is distinguishable.
  vec3 tint = 0.5 + 0.5*cos(float(row)*0.8 + vec3(0.0, 2.0, 4.0));
  float sep = step(0.02, fract(uv.y*8.0));   // thin separators
  o = vec4(bar*tint*sep, 1.0);
}`,
  channelKinds: ['none', 'none', 'none', 'none'],
  // Wire slots 1..8 to audio sources so the bars react on pick (else all 0).
  audioRouting: SWEEP_ROUTING,
};

/** 5. Buffer chain A→B→C→D dependency order — each buffer tints the previous
 * one, so the Image (D) must show all four tints stacked in order. A wrong or
 * missing tint proves buffers render out of order or a cross-buffer sample is
 * broken. */
const DEBUG_BUFFER_CHAIN: GlslPreset = {
  id: 'debug-buffer-chain',
  label: 'Debug · Buffer chain A→B→C→D order',
  description:
    'DEV: A→B→C→D each adds one color channel, sampling the previous buffer. Correct = all 4 tints stacked (white-ish center); missing tint = render-order or cross-buffer-sample bug.',
  source: `// EXPECTED: the four buffers accumulate colors in order — A adds a red ramp,
// B adds a green ramp (sampling A), C adds pulsing blue (sampling B), D passes
// C through. So the final image is a smooth red×green gradient with a blue
// pulse — the center trends toward white-ish. A MISSING color channel (no red,
// no green, or no blue) means a buffer rendered out of order or a cross-buffer
// sample failed.
void mainImage(out vec4 o, in vec2 fc){ o = texture(iChannel0, fc/iResolution.xy); }`,
  channelKinds: ['buffer', 'none', 'none', 'none'],
  bufferRefs: ['d', undefined, undefined, undefined],
  buffers: {
    a: {
      source: `void mainImage(out vec4 o, in vec2 fc){
  vec2 uv = fc/iResolution.xy;
  o = vec4(smoothstep(0.0,1.0,uv.x), 0.0, 0.0, 1.0);   // A: red ramp
}`,
      channelKinds: ['none', 'none', 'none', 'none'],
    },
    b: {
      source: `void mainImage(out vec4 o, in vec2 fc){
  vec2 uv = fc/iResolution.xy;
  vec3 a = texture(iChannel0, uv).rgb;                 // sample A
  o = vec4(a.r, smoothstep(0.0,1.0,uv.y), 0.0, 1.0);   // B: adds green
}`,
      channelKinds: ['buffer', 'none', 'none', 'none'],
      bufferRefs: ['a', undefined, undefined, undefined],
    },
    c: {
      source: `void mainImage(out vec4 o, in vec2 fc){
  vec2 uv = fc/iResolution.xy;
  vec3 b = texture(iChannel0, uv).rgb;                 // sample B
  o = vec4(b.r, b.g, 0.5+0.5*sin(iTime), 1.0);         // C: adds blue
}`,
      channelKinds: ['buffer', 'none', 'none', 'none'],
      bufferRefs: ['b', undefined, undefined, undefined],
    },
    d: {
      source: `void mainImage(out vec4 o, in vec2 fc){
  vec2 uv = fc/iResolution.xy;
  vec3 c = texture(iChannel0, uv).rgb;                 // sample C
  o = vec4(c, 1.0);                                    // D: passthrough (all tints)
}`,
      channelKinds: ['buffer', 'none', 'none', 'none'],
      bufferRefs: ['c', undefined, undefined, undefined],
    },
  },
};

/** 6. iChannelResolution / intensity probe — needs an uploaded image on
 * iChannel0. Left half shows the image scaled by iChannelIntensity[0]; right
 * half visualizes iChannelResolution[0] as a color (r=w/2048, g=h/2048). A
 * zero/garbage resolution (the 1/0-texel class of bug) shows as black on the
 * right; the intensity uniform not tracking shows as a static left half. */
const DEBUG_RES_INTENSITY: GlslPreset = {
  id: 'debug-res-intensity',
  label: 'Debug · iChannelResolution / intensity probe',
  description:
    'DEV: upload an image to iChannel0. Left = image × iChannelIntensity[0]; right = iChannelResolution[0] encoded as color. Black right half = resolution uniform is 0 (the 1/0-texel bug class).',
  source: `// EXPECTED: split screen. LEFT half = your uploaded image, its brightness
// scaled by iChannelIntensity[0] (drops to black as intensity → 0). RIGHT half
// = iChannelResolution[0] encoded as color (red = width/2048, green =
// height/2048), so a real resolution shows a steady dark-red/green tone. A
// BLACK right half means the resolution uniform is 0 — the 1/0-texel bug class.
void mainImage(out vec4 o, in vec2 fc){
  vec2 uv = fc/iResolution.xy;
  if (uv.x < 0.5) {
    vec3 img = texture(iChannel0, uv*vec2(2.0,1.0)).rgb;
    o = vec4(img * iChannelIntensity[0], 1.0);          // intensity scalar
  } else {
    vec3 res = vec3(iChannelResolution[0].xy / 2048.0, 0.0);  // encode w,h
    o = vec4(res, 1.0);
  }
}`,
  channelKinds: ['image2d', 'none', 'none', 'none'],
};

/** All dev-only debug presets, appended to the dropdown in development. */
export const DEV_DEBUG_PRESETS: GlslPreset[] = [
  DEBUG_SELF_FEEDBACK,
  DEBUG_CUBEMAP_ORIENTATION,
  DEBUG_ALL_NONE,
  DEBUG_UVALUE_SWEEP,
  DEBUG_BUFFER_CHAIN,
  DEBUG_RES_INTENSITY,
];
